import { toCents, applyTax, formatMoney } from "./helper.mjs";
export function formatTotal(items, rate, currency) {
  if (!Array.isArray(items)) {
    throw new TypeError("items");
  }
  let totalCents = 0;
  for (const price of items) {
    totalCents += toCents(price);
  }
  const taxedCents = applyTax(totalCents, rate);
  return formatMoney({ cents: taxedCents, currency });
}
